{
    public static void Main()
    {
        AutoCADChatGPTBridge bridge = new AutoCADChatGPTBridge();

        // Example chat message to draw a rectangle
        string chatMessage = "RECTANGLE 100 100 200 50";

        bridge.DrawUsingChatGPT(chatMessage);
    }
}
```

